previewCss:
.darma-loader-darma-b13-chat-bubble-exchange { --accent: var(--loader-color, #2563eb); --accent-2: var(--loader-secondary-color, #22c55e); width: var(--loader-size, 112px); height: calc(var(--loader-size, 112px) * .7); position: relative; }
.darma-loader-darma-b13-chat-bubble-exchange span { position: absolute; width: 62%; height: 42%; border-radius: 14px; animation: darma-loader-darma-b13-chat-bubble-exchange-bubble-in calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.35, 1.5, .5, 1) infinite; }
.darma-loader-darma-b13-chat-bubble-exchange span:nth-child(1) { left: 0; top: 0; transform-origin: bottom left; border-bottom-left-radius: 3px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 16%, var(--accent))); }
.darma-loader-darma-b13-chat-bubble-exchange span:nth-child(2) { right: 0; bottom: 0; transform-origin: bottom right; border-bottom-right-radius: 3px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 16%, var(--accent-2))); animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
.darma-loader-darma-b13-chat-bubble-exchange span::after { content: ''; position: absolute; top: 40%; left: 22%; width: 9%; height: 21%; border-radius: 50%; background: rgba(255, 255, 255, .92); box-shadow: 200% 0 0 rgba(255, 255, 255, .92), 400% 0 0 rgba(255, 255, 255, .92); }
@keyframes darma-loader-darma-b13-chat-bubble-exchange-bubble-in { 0% { opacity: 0; transform: scale(0); } 14% { opacity: 1; transform: scale(1.06); } 22%, 52% { transform: scale(1); } 68%, 100% { opacity: .22; transform: scale(1); } }

